358	{"id":"wNqeTKj68eF0lqFJ","name":"Assistant e-mails Telegram","nodes":[{"parameters":{"multipleMethods":false,"httpMethod":"POST","path":"assistant-mails-0e623b6c920aa52f22bb7772","authentication":"headerAuth","responseMode":"lastNode","responseData":"firstEntryJson","options":{}},"type":"n8n-nodes-base.webhook","typeVersion":2,"position":[0,0],"id":"da1a8ff1-7b1d-4916-ae96-054a451d0d96","name":"Webhook Telegram","credentials":{"httpHeaderAuth":{"id":"86dpp3Vg9wZOdnpT","name":"Pont Telegram (secret)"}},"webhookId":"17a4c956-8f6a-4b73-89a3-d2c3c624a13a"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Réception d'une mise à jour Telegram : filtre l'expéditeur, évite les doublons, retrouve la conversation en cours\\nconst ALLOWED = 8848139246;\\nconst upd = $input.first().json.body || {};\\nconst sd = $getWorkflowStaticData('global');\\nsd.seen = sd.seen || [];\\nsd.sessions = sd.sessions || {};\\n\\nconst msg = upd.message, cb = upd.callback_query;\\nconst from = (msg && msg.from) || (cb && cb.from) || {};\\nconst chat = (msg && msg.chat) || (cb && cb.message && cb.message.chat) || {};\\n\\n// seul le compte de Valentin est autorisé : tout autre expéditeur est ignoré sans réponse\\nif (Number(from.id) !== ALLOWED || Number(chat.id) !== ALLOWED) return [];\\n\\n// une même mise à jour n'est jamais traitée deux fois\\nif (upd.update_id !== undefined) {\\n  if (sd.seen.includes(upd.update_id)) return [];\\n  sd.seen.push(upd.update_id);\\n  if (sd.seen.length > 100) sd.seen = sd.seen.slice(-100);\\n}\\n\\nconst key = String(chat.id);\\nlet s = sd.sessions[key];\\nif (s && Date.now() - (s.updated || 0) > 45 * 60 * 1000) { delete sd.sessions[key]; s = undefined; } // conversation expirée après 45 min\\n\\nlet route = 'message', text = '';\\nif (cb) route = 'callback';\\nelse if (msg && msg.text) route = 'claude';\\nelse text = \\"Je ne sais traiter que du texte pour l'instant. Écrivez-moi (ou dictez avec le clavier de votre téléphone) à qui écrire, le sujet et ce qu'il faut dire.\\";\\n\\nreturn [{ json: {\\n  route, text, chat_id: chat.id, update_id: upd.update_id,\\n  user_text: msg ? (msg.text || '') : '',\\n  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',\\n  session: s || null,\\n} }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[250,0],"id":"553fcad7-f3e2-4eb3-a743-4c5557786be6","name":"Normaliser la mise à jour"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"2eb2cd49-dbd0-48b0-b32d-c35ab46f8353","leftValue":"={{ $json.route }}","rightValue":"callback","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,0],"id":"2265e5f5-cc68-4f9c-83e2-32b62bb81457","name":"Bouton ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"756deb36-156c-44f2-8d26-fdb8ad9ee285","leftValue":"={{ $json.route }}","rightValue":"claude","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,400],"id":"cc121581-ebad-4fdf-812c-1ad69244c3d2","name":"Demande à Claude ?"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"none","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,400],"id":"d9990c52-938b-489a-8039-5fc0de70214f","name":"Message texte","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"e6a6c79c-ef69-4a50-b40a-fbf2ab831b1c"},{"parameters":{"resource":"callback","operation":"answerQuery","queryId":"={{ $json.cb_id }}","additionalFields":{}},"type":"n8n-nodes-base.telegram","