Digest quotidien 7h - v.caufriez	t	[{"parameters":{"rule":{"interval":[{"field":"cronExpression","expression":"0 7 * * *"}]}},"type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.2,"position":[0,0],"id":"d1a1b111-0000-4000-8000-000000000001","name":"Schedule Trigger 7h"},{"parameters":{"method":"GET","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendQuery":true,"queryParameters":{"parameters":[{"name":"limit","value":"250"}]},"options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[224,0],"id":"d1a1b111-0000-4000-8000-000000000002","name":"Get digest_mails rows","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}},{"parameters":{"jsCode":"const rows = $input.first().json.data || [];\\n\\nconst LIMIT = 3800; // limite Telegram : 4096 caractères par message\\nconst LABELS = { 'v.caufriez': 'v.caufriez@ebanista.fr', 'contact': 'contact@ebanista.fr', 'comptabilite': 'comptabilite@ebanista.fr' };\\nconst ORDER = ['v.caufriez', 'contact', 'comptabilite'];\\n\\nif (rows.length === 0) {\\n  return [{ json: { text: \\"📋 Digest quotidien EBANISTA\\\\n\\\\nAucun mail à traiter aujourd'hui.\\", count: 0 } }];\\n}\\n\\n// regroupement par boîte (les anciennes lignes sans boîte viennent de v.caufriez)\\nconst groups = {};\\nfor (const r of rows) {\\n  const box = r.boite || 'v.caufriez';\\n  (groups[box] = groups[box] || []).push(r);\\n}\\nconst boxes = [...ORDER.filter(b => groups[b]), ...Object.keys(groups).filter(b => !ORDER.includes(b))];\\n\\n// un bloc de texte par boîte, puis découpage en messages de taille raisonnable\\nconst blocks = [];\\nfor (const box of boxes) {\\n  const list = groups[box];\\n  blocks.push(`📥 ${LABELS[box] || box} (${list.length})`);\\n  for (const r of list) {\\n    blocks.push(`• [${r.categorie}] ${r.expediteur}\\\\n  ${r.resume}`);\\n  }\\n}\\n\\nconst header = `📋 Digest quotidien EBANISTA — ${rows.length} mail(s)`;\\nconst chunks = [];\\nlet current = header;\\nfor (const b of blocks) {\\n  const next = current + '\\\\n\\\\n' + b;\\n  if (next.length > LIMIT && current !== header) {\\n    chunks.push(current);\\n    current = '(suite)\\\\n\\\\n' + b;\\n  } else {\\n    current = next;\\n  }\\n}\\nchunks.push(current);\\n\\nreturn chunks.map(text => ({ json: { text, count: rows.length } }));\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[448,0],"id":"d1a1b111-0000-4000-8000-000000000003","name":"Build digest text"},{"parameters":{"chatId":"8848139246","text":"={{ (($json.text)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","additionalFields":{"appendAttribution":false,"parse_mode":"HTML"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[672,0],"id":"d1a1b111-0000-4000-8000-000000000004","name":"Send digest to Telegram","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"363c01d7-51fe-4fad-9eaa-5b88407a022d"},{"parameters":{"method":"DELETE","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows/clear","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[896,0],"id":"d1a1b111-0000-4000-8000-000000000005","name":"Clear digest_mails table","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}}]	{"Schedule Trigger 7h":{"main":[[{"node":"Get digest_mails rows","type":"main","index":0}]]},"Get digest_mails rows":{"main":[[{"node":"Build digest text","type":"main","index":0}]]},"Build digest text":{"main":[[{"node":"Send digest to Telegram","type":"main","index":0}]]},"Send digest to Telegram":{"main":[[{"node":"Clear digest_mails table","type":"main","index":0}]]}}	2026-08-16 15:57:53.942+00	2026-10-09 20:36:46.83+00	{"executionOrder":"v1"}	{"node:Schedule Trigger 7h":{"recurrenceRules":[null],"recurrence