re_fournisseur: 'Tri-Offre fournisseur',\\n  confirmation_commande: 'Tri-Confirmation de commande',\\n  prospects: 'Tri-Prospects',\\n  suivi_client: 'Tri-SuiviClient',\\n  administratif: 'Tri-Administratif',\\n  litige: 'Tri-Litige',\\n  facturation: 'Tri-Facturation',\\n  spam: 'Spam'\\n};\\n\\n// Traite TOUS les mails d'un lot (plusieurs mails peuvent arriver en même temps)\\nreturn $input.all().map((entry, i) => {\\n  const item = entry.json;\\n  const targetFolder = folderMap[item.categorie] || 'Tri-Administratif';\\n  // Pas de réponse automatique sur cette boîte : seul le spam est marqué lu.\\n  const markAsRead = item.categorie === 'spam';\\n  return { json: { ...item, targetFolder, markAsRead }, pairedItem: { item: i } };\\n});"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1344,288],"id":"f1a1b111-0000-4000-8000-000000000020","name":"Déterminer dossier cible"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"moveEmail","sourceMailbox":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","destinationMailbox":{"__rl":true,"mode":"path","value":"={{ $('Déterminer dossier cible').item.json.targetFolder }}"}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1568,288],"id":"f1a1b111-0000-4000-8000-000000000021","name":"Déplacer le mail","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f003","leftValue":"={{ $json.markAsRead }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,200],"id":"f1a1b111-0000-4000-8000-000000000022","name":"Faut-il marquer lu ?"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","flags":{"\\\\Seen":true}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1792,144],"id":"f1a1b111-0000-4000-8000-000000000023","name":"Marquer comme lu","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"amount":1},"type":"n8n-nodes-base.wait","typeVersion":1.1,"position":[1792,144],"id":"f1a1b111-0000-4000-8000-000000000024","name":"Attendre 8s","webhookId":"a0113614-411e-4451-8f6e-24805da6f086"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"d2000000-0000-4000-8000-00000000f001","leftValue":"={{ $json.reponse_requise }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}},{"id":"d2000000-0000-4000-8000-00000000f002","leftValue":"={{ $('Email Trigger (IMAP)').item.json.from.text }}","rightValue":"/(no[-_. ]?reply|ne[-_. ]?pas[-_. ]?r[eé]pondre|do[-_. ]?not[-_. ]?reply|mailer-daemon|postmaster|bounces?@)/i","operator":{"type":"string","operation":"notRegex"}},{"id":"d2000000-0000-4000-8000-00000000f003","leftValue":"={{ ($('Email Trigger (IMAP)').item.json.from.value || [{}])[0].address || '' }}","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,-480],"id":"d2000000-0000-4000-8000-000000000041","name":"Réponse à préparer ?"},{"parameters":{"jsCode":"// Prépare, pour chaque mail à traiter, les données envoyées au sous-workflow de rédaction\\nreturn $input.all().map((entry, i) => {\\n  const mail = $('Email Trigger (IMAP)').itemMatching(i).json;\\n  const from = (mail.from && mail.from.value && mail.from.value[0]) || {};\\n  return {\\n    json: {\\n      from_address: from.address || '