 formule de politesse et la signature \\"L'équipe EBANISTA\\""}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[1792,336],"id":"f1a1b111-0000-4000-8000-000000000013","name":"Rédiger accusé personnalisé"},{"parameters":{"jsCode":"const folderMap = {\\n  offre_fournisseur: 'Tri-Offre fournisseur',\\n  confirmation_commande: 'Tri-Confirmation de commande',\\n  prospects: 'Tri-Prospects',\\n  suivi_client: 'Tri-SuiviClient',\\n  administratif: 'Tri-Administratif',\\n  litige: 'Tri-Litige',\\n  facturation: 'Tri-Facturation',\\n  spam: 'Spam'\\n};\\n\\n// Traite TOUS les mails d'un lot (plusieurs mails peuvent arriver en même temps)\\nreturn $input.all().map((entry, i) => {\\n  const item = entry.json;\\n  const targetFolder = folderMap[item.categorie] || 'Tri-Administratif';\\n  // Marqué comme lu uniquement si aucune action de votre part n'est nécessaire : réponse automatisée, ou spam.\\n  const markAsRead = item.auto_envoi_possible === true || item.categorie === 'spam';\\n  return { json: { ...item, targetFolder, markAsRead }, pairedItem: { item: i } };\\n});"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1344,288],"id":"f1a1b111-0000-4000-8000-000000000020","name":"Déterminer dossier cible"},{"parameters":{"authentication":"imapThisNode","resource":"email","operation":"moveEmail","sourceMailbox":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","destinationMailbox":{"__rl":true,"mode":"path","value":"={{ $('Déterminer dossier cible').item.json.targetFolder }}"}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1568,288],"id":"f1a1b111-0000-4000-8000-000000000021","name":"Déplacer le mail","credentials":{"imapApi":{"id":"7D7EF7hYzLreslfS","name":"IMAP Move - v.caufriez@ebanista.fr"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-0