 à qui écrire, le sujet et ce qu'il faut dire.\\";\\n\\nreturn [{ json: {\\n  route, text, chat_id: chat.id, update_id: upd.update_id,\\n  user_text: msg ? (msg.text || '') : '',\\n  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',\\n  session: s || null,\\n} }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[250,0],"id":"5c9e316a-d61b-45b2-92c1-307c3841acc8","name":"Normaliser la mise à jour"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"14a2e202-5158-4f83-a393-f8c92c1fe15d","leftValue":"={{ $json.route }}","rightValue":"callback","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,0],"id":"2d073d63-73d5-4137-af68-497502eac9a0","name":"Bouton ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"05cc763f-a6d7-4ec2-bae1-c8bfb2198c70","leftValue":"={{ $json.route }}","rightValue":"claude","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,400],"id":"c749047e-bc6e-4b41-abd3-e0ae606eff7c","name":"Demande à Claude ?"},{"parameters":{"chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,400],"id":"20bfffb4-a392-4544-a203-2bdfc66c4b5c","name":"Message texte","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"5fe5059c-efd0-4579-bbb6-bb7110065e47"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"ac6df906-4306-4c56-915c-019238f37ae2","leftValue":"={{ $json.route }}","rightValue":"message","operator":{"type":"string","operation":"equals"}}],"c