[m[1]];\\ns.state = 'sending'; s.updated = Date.now();\\nconst d = s.draft;\\nreturn [{ json: {\\n  chat_id: j.chat_id, next: 'send', box: m[1], label: BOX.label,\\n  from: BOX.from, fromName: BOX.fromName,\\n  from_header: `${BOX.fromName} <${BOX.from}>`,\\n  to: d.to_address, to_name: d.to_name || '', subject: d.subject || '(sans objet)',\\n  text: `${d.body.replace(/\\\\s+$/, '')}\\\\n\\\\n${BOX.signature}`,\\n} }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1000,-200],"id":"cab6e1df-ca33-4b41-80b6-391d3e0d4f03","name":"Traiter le bouton"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"dce91afc-e56c-40bf-9b16-2bc77969fe83","leftValue":"={{ $json.next }}","rightValue":"send","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1250,-200],"id":"01365f67-0c4e-48bc-a3cf-ecd483fadf98","name":"Envoi demandé ?"},{"parameters":{"jsCode":"// Confirme l'envoi à Valentin et clôt la conversation\\nconst t = $('Traiter le bouton').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\ndelete sd.sessions[String(t.chat_id)];\\nlet copyOk = true;\\ntry {\\n  const r = $input.first().json;\\n  if (!r || r.error || r.deleted === false) copyOk = false;\\n} catch (e) { copyOk = false; }\\nreturn [{ json: { chat_id: t.chat_id, text: `✅ Mail envoyé depuis ${t.label}\\\\nÀ : ${t.to}\\\\nObjet : ${t.subject}` + (copyOk ? '\\\\nUne copie est enregistrée dans Envoyés.' : \\"\\\\n⚠️ La copie dans Envoyés n'a pas pu être enregistrée.\\") } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2150,-200],"id":"65f87429-055d-43f1-9209-f9c600fb6c99","name":"Confirmer l'envoi"},{"parameters":{"chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.