ueErrorOutput","webhookId":"77d532b0-7cf9-4f6d-ae31-190647744d21"},{"parameters":{"jsCode":"// Compose la copie du mail envoyé (RFC822) pour le dossier Envoyés de la boîte\\nconst t = $('Traiter le bouton').first().json;\\nconst info = $input.first().json;\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst name = (n) => !n ? '' : (!isAscii(n) ? `=?UTF-8?B?${b64(n)}?=` : (/[^\\\\w .'-]/.test(n) ? `\\"${n.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : n));\\nconst msgId = info.messageId || `<copie-${Date.now()}@ebanista.fr>`;\\nconst headers = [\\n  `From: ${name(t.fromName)} <${t.from}>`,\\n  `To: ${t.to_name ? name(t.to_name) + ' ' : ''}<${t.to}>`,\\n  `Subject: ${encodeHeader(t.subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: ${msgId}`,\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst body = b64(t.text.replace(/\\\\r?\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + body + CRLF } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1900,-200],"id":"118747f3-aada-4453-b013-0ff1e5cd2123","name":"Composer la copie v"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Sent"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,-200],"id":"b7f6c673-c918-44f6-bc78-84951cacadfc","name":"Enregistrer la copie v","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailUid":"={{ $json.uid }}","flags":{"\\\\Seen":true,"\\\\Draft":false}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2100,-200],"id":"bd4337c5-673b-4cfc-9bac-de0a182bdb53","name":"Marquer la copie lue v","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"fromEmail":"={{ $json.from_header }}","toEmail":"={{ $json.to }}","subject":"={{ $json.subject }}","emailFormat":"text","text":"={{ $json.text }}","options":{"appendAttribution":false}},"type":"n8n-nodes-base.emailSend","typeVersion":2.1,"position":[1700,50],"id":"f119e4f7-e4cc-4b3b-a541-ceaff23627b8","name":"Envoi depuis contact@ebanista.fr","credentials":{"smtp":{"id":"4znohlVNgQDzDtyl","name":"SMTP - contact@ebanista.fr"}},"onError":"continueErrorOutput","webhookId":"2067da6a-6b38-43b3-8b0c-e6d88714b3b5"},{"parameters":{"jsCode":"// Compose la copie du mail envoyé (RFC822) pour le dossier Envoyés de la boîte\\nconst t = $('Traiter le bouton').first().json;\\nconst info = $input.first().json;\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst name = (n) => !n ? '' : (!isAscii(n) ? `=?UTF-8?B?${b64(n)}?=` : (/[^\\\\w .'-]/.test(n) ? `\\"${n.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : n));\\nconst msgId = info.messageId || `<copie-${Date.now()}@ebanista.fr>`;\\nconst headers = [\\n  `From: ${name(t.fromName)} <${t.from}>`,\\n  `To: ${t.to_name ? name(t.to_name) + ' ' : ''}<${t.to}>`,\\n  `Subject: ${encodeHeader(t.subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: ${msgId}`,\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst body = b64(t.text.replace(/\\\\r?\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + body + CRLF } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1900,50],"id":"0ba4e68c-34da-4a42-8dda-2c039d193675","name":"Composer la copie c"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Sent"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,50],"id":"327d3293-54bf-4541-b8e0-6becd5097b0c","name":"Enregistrer la copie c","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailUid":"={{ $json.uid }}","flags":{"\\\\Seen":true,"\\\\Draft":false}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2100,50],"id":"f29405fb-deb1-4780-9e97-7b51ba4a3f9c","name":"Marquer la copie lue c","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// Construit le message envoyé à Claude : demande de Valentin + brouillon en cours + adresses proposées\\nconst j = $input.first().json;\\nconst s = j.session;\\nconst parts = ['MESSAGE DE VALENTIN :', j.user_text];\\nif (s && s.draft && s.draft.body) {\\n  const d = s.draft;\\n  parts.push('', 'BROUILLON EN COURS :', `À : ${d.to_name || ''} <${d.to_address || 'adresse inconnue'}>`, `Objet : ${d.subject || ''}`, 'Corps :', d.body);\\n}\\nif (s && s.candidates && s.candidates.length) {\\n  parts.push('', 'ADRESSES PROPOSÉES POUR LE DESTINATAIRE (il peut répondre par un numéro) :');\\n  s.candidates.forEach((c, i) => parts.push(`${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`));\\n}\\nreturn [{ json: { ...j, prompt: parts.join('\\\\n') } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[750,400],"id":"9efd1c43-36c9-4069-96bb-b89091127c35","name":"Préparer l'appel Claude"},{"parameters":{"promptType":"define","text":"={{ $json.prompt }}","messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu es l'assistant de rédaction d'e-mails de Valentin Caufriez, gérant d'EBANISTA (menuiserie / ébénisterie sur mesure). Valentin te dicte par Telegram, en langage courant, un e-mail à envoyer (destinataire, sujet, contenu). Tu rédiges l'e-mail à sa place, dans son style ; ensuite il choisit la boîte d'envoi et valide.\\n\\nTu reçois son message, et éventuellement le brouillon en cours (à réviser) et une liste numérotée d'adresses proposées.\\n\\nRéponds UNIQUEMENT par un objet JSON, sans texte autour :\\n{\\n  \\"intent\\": \\"draft\\" | \\"revise\\" | \\"cancel\\" | \\"other\\",\\n  \\"to_name\\": \\"nom du destinataire\\" ou null,\\n  \\"to_address\\": \\"adresse e-mail\\" ou null,\\n  \\"subject\\": \\"objet\\" ou null,\\n  \\"body\\": \\"corps complet du mail, formule de politesse comprise, SANS signature\\" ou null,\\n  \\"reply\\": \\"message court à afficher à Valentin\\" ou null\\n}\\n\\nINTENTIONS :\\n- \\"draft\\" : nouvelle demande d'e-mail.\\n- \\"revise\\" : il modifie le brouillon en cours (ajoute, retire, raccourcit, change le ton, corrige un détail). Change uniquement ce qui est demandé, garde le reste, et renvoie le mail complet à jour.\\n- \\"cancel\\" : il abandonne ce brouillon.\\n- \\"other\\" : ce n'est pas une demande de mail (question, remerciement, message flou). Réponds brièvement dans \\"reply\\" et explique au besoin comment demander un mail : à qui, quel sujet, ce qu'il faut dire.\\n\\nDESTINATAIRE :\\n- to_address : seulement si une adresse figure dans son message ou dans le brouillon en cours, ou s'il choisit un numéro dans la liste d'adresses proposées. N'invente JAMAIS une adresse e-mail. Sinon null (avec to_name si tu as un nom).\\n- Si l'objet n'est pas dicté, propose un objet court et pertinent.\\n\\nSTYLE DU CORPS (celui de Valentin) :\\n- Court et direct, 3 à 8 lignes en général, paragraphes très courts, aucune formule ampoulée.\\n- Vouvoiement par défaut ; tutoiement (\\"Salut Prénom,\\") seulement s'il le demande ou indique que le destinataire est un proche ou un fournisseur habituel.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Salut Prénom,\\" en tutoiement.\\n- Commandes et demandes de prix : liste à tirets, une quantité ou une référence par ligne.\\n- Termine par une formule de politesse seule : \\"Cordialement,\\" (ou \\"À bientôt,\\" / \\"Bien à toi,\\" en tutoiement). Ne mets AUCUN nom ni signature après : la signature est ajoutée automatiquement.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un prix, un délai, une date, une quantité, une référence, une dimension ni un engagement qu'il n'a pas dicté. S'il manque une information indispensable, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Ne mets pas l'objet dans le corps. N'ajoute ni commentaire, ni \\"Voici le mail\\".\\n- Écris en français, sauf si Valentin demande une autre langue."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[1000,400],"id":"e0ffca86-e590-485a-a525-a7d06ea3d1dd","name":"Rédiger avec Claude"},{"parameters":{"model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.3}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[1040,620],"id":"5b8ae886-766f-40d5-aee7-72f4f29652c7","name":"Modèle Claude (assistant)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"jsCode":"// Applique la réponse de Claude à la conversation (brouillon, annulation, question) et décide de la suite\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst raw = String($input.first().json.text || '');\\nlet out = null;\\ntry { out = JSON.parse(raw.match(/\\\\{[\\\\s\\\\S]*\\\\}/)[0]); } catch (e) { out = null; }\\n\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\nconst key = String(j.chat_id);\\nconst prev = sd.sessions[key];\\nconst say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];\\n\\nif (!out) return say(\\"Je n'ai pas bien compris. Pouvez-vous reformuler votre demande d'e-mail ?\\");\\nif (out.intent === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }\\nif (out.intent === 'other') return say(out.reply || \\"Dites-moi à qui écrire, le sujet et ce qu'il faut dire, et je prépare le mail.\\");\\n\\nconst okMail = (a) => (typeof a === 'string' && /^[^\\\\s@<>]+@[^\\\\s@<>]+\\\\.[^\\\\s@<>]+$/.test(a.trim())) ? a.trim() : null;\\nconst d = (prev && prev.draft) || {};\\nlet nd;\\nif (out.intent === 'revise' && prev && prev.draft) {\\n  nd = {\\n    to_name: out.to_name || d.to_name || null,\\n    to_address: okMail(out.to_address) || d.to_address || null,\\n    subject: out.subject || d.subject || null,\\n    body: out.body || d.body || null,\\n  };\\n} else {\\n  nd = { to_name: out.to_name || null, to_address: okMail(out.to_address), subject: out.subject || null, body: out.body || null };\\n}\\nsd.sessions[key] = { state: 'draft', draft: nd, candidates: null, updated: Date.now() };\\n\\nif (!nd.body) return say(out.reply || 'Que voulez-vous dire dans ce mail ?');\\nconst needLookup = !nd.to_address && !!nd.to_name;\\nreturn [{ json: { chat_id: j.chat_id, next: needLookup ? 'lookup' : 'decide', lookup_name: nd.to_name || '' } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1250,400],"id":"4c9327b6-13e8-4022-bf81-379051d60c23","name":"Appliquer la réponse de Claude"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f9df227d-c571-42b6-881d-7c27450bd250","leftValue":"={{ $json.next }}","rightValue":"message","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1500,400],"id":"be4b4f61-10e6-4a66-850c-5f3b09d12044","name":"Message direct ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"4bcc2e05-86ef-4f88-ba28-e04671401a80","leftValue":"={{ $json.next }}","rightValue":"lookup","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1750,550],"id":"84550032-ffa5-4b84-a918-c4d123373255","name":"Recherche d'adresse ?"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 2 }).toISO() }}"},"emailSearchFilters":{"to":"={{ ($('Appliquer la réponse de Claude').first().json.lookup_name || '').split(/\\\\s+/).filter(Boolean).sort((a, b) => b.length - a.length)[0] || 'introuvable-xyz' }}"},"limit":40,"includeParts":[]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,700],"id":"18de5824-7173-4ad0-9030-1fa7d46734f2","name":"Recherche Envoyés v.caufriez","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"alwaysOutputData":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// Regroupe en un seul élément les résultats de la recherche dans les Envoyés de v.caufriez@\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\nreturn [{ json: { found } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2200,700],"id":"929ac7dc-fe8e-4cd3-9536-d98c4732e7ab","name":"Regrouper les résultats v.caufriez"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 2 }).toISO() }}"},"emailSearchFilters":{"to":"={{ ($('Appliquer la réponse de Claude').first().json.lookup_name || '').split(/\\\\s+/).filter(Boolean).sort((a, b) => b.length - a.length)[0] || 'introuvable-xyz' }}"},"limit":40,"includeParts":[]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2400,700],"id":"e89a4cf3-9b84-41e7-a047-fbec7f044b29","name":"Recherche Envoyés contact","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}},"alwaysOutputData":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// Retrouve l'adresse du destinataire à partir de son nom, dans les dossiers Envoyés des deux boîtes\\nconst ctx = $('Appliquer la réponse de Claude').first().json;\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst key = String(j.chat_id);\\nconst s = sd.sessions[key];\\nconst strip = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\\nconst tokens = strip(ctx.lookup_name).split(/[^a-z0-9]+/).filter(t => t.length >= 2);\\n\\nconst first = ($('Regrouper les résultats v.caufriez').first().json.found) || [];\\nconst second = $input.all().map(i => i.json).filter(x => x && x.envelope && !x.error);\\nconst MINE = ['v.caufriez@ebanista.fr', 'contact@ebanista.fr', 'comptabilite@ebanista.fr'];\\nconst tally = {};\\nfor (const m of [...first, ...second]) {\\n  for (const t of ((m.envelope && m.envelope.to) || [])) {\\n    const addr = String(t.address || '').toLowerCase();\\n    if (!addr || MINE.includes(addr)) continue;\\n    const hay = strip((t.name || '') + ' ' + addr);\\n    if (tokens.length && !tokens.every(tok => hay.includes(tok))) continue;\\n    const e = tally[addr] || (tally[addr] = { address: addr, name: t.name || '', count: 0 });\\n    e.count++;\\n    if (!e.name && t.name) e.name = t.name;\\n  }\\n}\\nconst list = Object.values(tally).sort((a, b) => b.count - a.count);\\nif (s) {\\n  if (list.length === 1 || (list.length > 1 && list[0].count >= 2 * list[1].count && list[0].count >= 2)) {\\n    s.draft.to_address = list[0].address;\\n    if (!s.draft.to_name && list[0].name) s.draft.to_name = list[0].name;\\n  } else if (list.length > 1) {\\n    s.candidates = list.slice(0, 5).map(c => ({ name: c.name, address: c.address }));\\n  }\\n  s.updated = Date.now();\\n}\\nreturn [{ json: { chat_id: j.chat_id } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2600,700],"id":"b63e21ec-0167-430f-8904-30c6fa456e8a","name":"Retrouver l'adresse"},{"parameters":{"jsCode":"// Décide ce qu'il faut répondre à Valentin : question sur l'adresse, informations manquantes, ou aperçu avec boutons\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst key = String(j.chat_id);\\nconst s = sd.sessions[key];\\nconst out = (text, preview = false) => [{ json: { chat_id: j.chat_id, text, preview } }];\\nif (!s || !s.draft) return out(\\"Je n'ai plus de brouillon en cours. Redites-moi à qui écrire et ce qu'il faut dire.\\");\\nconst d = s.draft;\\n\\nif (s.candidates && s.candidates.length) {\\n  s.state = 'awaiting_address'; s.updated = Date.now();\\n  const lines = s.candidates.map((c, i) => `${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`).join('\\\\n');\\n  return out(`Plusieurs adresses possibles pour « ${d.to_name || 'ce destinataire'} » :\\\\n${lines}\\\\n\\\\nRépondez par le numéro, ou donnez-moi directement l'adresse.`);\\n}\\nif (!d.to_address) {\\n  s.state = 'awaiting_address'; s.updated = Date.now();\\n  return out(`Je n'ai pas trouvé l'adresse e-mail de ${d.to_name || 'ce destinataire'}. Pouvez-vous me la donner ?`);\\n}\\nconst missing = (d.body.match(/\\\\[À COMPLÉTER[^\\\\]]*\\\\]/g) || []);\\nconst draftText = `À : ${d.to_name ? d.to_name + ' ' : ''}<${d.to_address}>\\\\nObjet : ${d.subject || '(sans objet)'}\\\\n\\\\n${d.body}`;\\nif (missing.length) {\\n  s.state = 'awaiting_info'; s.updated = Date.now();\\n  return out(`Il manque des informations avant de pouvoir envoyer :\\\\n${missing.map(m => '• ' + m).join('\\\\n')}\\\\n\\\\nPrécisez-les-moi et je mets le brouillon à jour.\\\\n\\\\n— Brouillon actuel —\\\\n${draftText}`);\\n}\\ns.state = 'ready'; s.updated = Date.now();\\nreturn out(`✉️ Brouillon prêt\\\\n\\\\n${draftText}\\\\n\\\\n(La signature est ajoutée selon la boîte choisie.)\\\\nChoisissez la boîte d'envoi, ou dites-moi quoi modifier.`, true);\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2800,550],"id":"14aa7244-434d-4fd4-bc7d-94289d20962a","name":"Décider du message"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"9390c1cc-55de-4934-ab69-a14ebd53158d","leftValue":"={{ String($json.preview) }}","rightValue":"true","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[3050,550],"id":"383199b9-459c-4d27-a681-2ca6e9c1372d","name":"Aperçu ?"},{"parameters":{"chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"inlineKeyboard","inlineKeyboard":{"rows":[{"row":{"buttons":[{"text":"✉️ Envoyer depuis v.caufriez@ebanista.fr","additionalFields":{"callback_data":"send:v"}}]}},{"row":{"buttons":[{"text":"✉️ Envoyer depuis contact@ebanista.fr","additionalFields":{"callback_data":"send:c"}}]}},{"row":{"buttons":[{"text":"❌ Annuler","additionalFields":{"callback_data":"cancel"}}]}}]},"additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-ba