e58d0950-e2c4-4035-b04d-d121c1282494	n443xVZ8J3tVez1B	Valentin Caufriez	2026-10-09 18:38:35.746+00	2026-10-09 18:38:35.746+00	[{"parameters":{"format":"resolved","options":{"customEmailConfig":"[\\"UNSEEN\\", [\\"SINCE\\", \\"Oct 9, 2026\\"]]"},"postProcessAction":"nothing"},"type":"n8n-nodes-base.emailReadImap","typeVersion":2.2,"position":[0,0],"id":"4acf197b-93b5-4ffa-894d-e8cf9068550e","name":"Email Trigger (IMAP)","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"promptType":"define","text":"=Voici un email à analyser :\\nExpéditeur : {{ $json.from.text }}\\nSujet : {{ $json.subject }}\\nContenu : {{ $json.text }}\\n","messages":{"messageValues":[{"message":"Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[608,0],"id":"0c6fe25a-11e3-4c7e-b5ae-efd8a3629137","name":"Basic LLM Chain"},{"parameters":{"model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[992,0],"id":"9d47d40d-f929-4681-ab5c-711d775c9e1d","name":"Anthropic Chat Model","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"jsCode":"const results = [];\\n\\nfor (const item of $input.all()) {\\n  const rawText = item.json.text;\\n  const match = rawText.match(/\\\\{[\\\\s\\\\S]*\\\\}/);\\n  const parsed = JSON.parse(match[0]);\\n  \\n  results.push({\\n    json: {\\n      categorie: parsed.categorie,\\n      urgent: parsed.urgent,\\n      resume: parsed.resume,\\n      auto_envoi_possible: parsed.auto_envoi_possible\\n    }\\n  });\\n}\\n\\nreturn results;\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1120,144],"id":"10349273-435b-4320-b5fb-fbebf52de6a6","name":"Code in JavaScript"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f22f7138-265f-46e1-8325-3ff0776b55a7","leftValue":"={{ $json.urgent }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1344,144],"id":"0b6b1958-7db2-468c-bf33-935de9103024","name":"If"},{"parameters":{"chatId":"8848139246","text":"=🚨 Mail urgent reçu sur comptabilite@ebanista.fr\\n\\nDe : {{ $('Email Trigger (IMAP)').item.json.from.text }}\\nCatégorie : {{ $json.categorie }}\\n\\n{{ $json.resume }}\\n","additionalFields":{}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1568,48],"id":"a00d2675-2c89-4e0f-b077-76de969ad947","name":"Send a text message","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"590ae063-52c5-484e-a289-00f479478d5c"},{"parameters":{"dataTableId":{"__rl":true,"value":"IgT0r6Yg3ZtzMWNR","mode":"list","cachedResultName":"digest_mails","cachedResultUrl":"/projects/WBZOJkoq8ImSC8dI/datatables/IgT0r6Yg3ZtzMWNR"},"columns":{"mappingMode":"defineBelow","value":{"auto_envoye":"={{ false }}","expediteur":"={{ $('Email Trigger (IMAP)').item.json.from.text }}","categorie":"={{ $json.categorie }}","resume":"={{ $json.resume }}","date":"={{ $now.format('yyyy-MM-dd HH:mm') }}","boite":"comptabilite"},"matchingColumns":[],"schema":[{"id":"date","displayName":"date","required":false,"defaultMatch":false,"display":true,"type":"dateTime","readOnly":false,"removed":false},{"id":"expediteur","displayName":"expediteur","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"categorie","displayName":"categorie","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"resume","displayName":"resume","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"auto_envoye","displayName":"auto_envoye","required":false,"defaultMatch":false,"display":true,"type":"boolean","readOnly":false,"removed":false},{"id":"boite","displayName":"boite","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.dataTable","typeVersion":1.1,"position":[1568,240],"id":"122b45a3-88b0-46be-be02-8b79a661cf3f","name":"Insert row"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f001","leftValue":"={{ $json.categorie }}","rightValue":"spam","operator":{"type":"string","operation":"notEquals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.filter","typeVersion":2.2,"position":[1344,0],"id":"f1a1b111-0000-4000-8000-000000000010","name":"Filtrer spam"},{"parameters":{"jsCode":"const folderMap = {\\n  offre_fournisseur: 'Tri-Offre fournisseur',\\n  confirmation_commande: 'Tri-Confirmation de commande',\\n  prospects: 'Tri-Prospects',\\n  suivi_client: 'Tri-SuiviClient',\\n  administratif: 'Tri-Administratif',\\n  litige: 'Tri-Litige',\\n  facturation: 'Tri-Facturation',\\n  spam: 'Spam'\\n};\\n\\n// Traite TOUS les mails d'un lot (plusieurs mails peuvent arriver en même temps)\\nreturn $input.all().map((entry, i) => {\\n  const item = entry.json;\\n  const targetFolder = folderMap[item.categorie] || 'Tri-Administratif';\\n  // Pas de réponse automatique sur cette boîte : seul le spam est marqué lu.\\n  const markAsRead = item.categorie === 'spam';\\n  return { json: { ...item, targetFolder, markAsRead }, pairedItem: { item: i } };\\n});"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1344,288],"id":"f1a1b111-0000-4000-8000-000000000020","name":"Déterminer dossier cible"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"moveEmail","sourceMailbox":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","destinationMailbox":{"__rl":true,"mode":"path","value":"={{ $('Déterminer dossier cible').item.json.targetFolder }}"}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1568,288],"id":"f1a1b111-0000-4000-8000-000000000021","name":"Déplacer le mail","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f003","leftValue":"={{ $json.markAsRead }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,200],"id":"f1a1b111-0000-4000-8000-000000000022","name":"Faut-il marquer lu ?"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","flags":{"\\\\Seen":true}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1792,144],"id":"f1a1b111-0000-4000-8000-000000000023","name":"Marquer comme lu","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"amount":1},"type":"n8n-nodes-base.wait","typeVersion":1.1,"position":[1792,144],"id":"f1a1b111-0000-4000-8000-000000000024","name":"Attendre 8s","webhookId":"a0113614-411e-4451-8f6e-24805da6f086"}]	{"Anthropic Chat Model":{"ai_languageModel":[[{"node":"Basic LLM Chain","type":"ai_languageModel","index":0}]]},"Email Trigger (IMAP)":{"main":[[{"node":"Basic LLM Chain","type":"main","index":0}]]},"Basic LLM Chain":{"main":[[{"node":"Code in JavaScript","type":"main","index":0}]]},"Code in JavaScript":{"main":[[{"node":"Filtrer spam","type":"main","index":0},{"node":"Déterminer dossier cible","type":"main","index":0}]]},"If":{"main":[[{"node":"Send a text message","type":"main","index":0}],[]]},"Filtrer spam":{"main":[[{"node":"If","type":"main","index":0},{"node":"Insert row","type":"main","index":0}]]},"Déterminer dossier cible":{"main":[[{"node":"Faut-il marquer lu ?","type":"main","index":0}]]},"Faut-il marquer lu ?":{"main":[[{"node":"Marquer comme lu","type":"main","index":0}],[{"node":"Déplacer le mail","type":"main","index":0}]]},"Marquer comme lu":{"main":[[{"node":"Attendre 8s","type":"main","index":0}]]},"Attendre 8s":{"main":[[{"node":"Déplacer le mail","type":"main","index":0}]]}}	\N	f	\N	[]
d7b8972e-f4ed-479d-9f32-241a4b0b30eb	705Af47ZTs7QhMZd	Valentin Caufriez	2026-10-09 19:26:08.757+00	2026-10-09 19:26:08.757+00	[{"parameters":{"inputSource":"passthrough"},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1.1,"position":[0,0],"id":"a1000000-0000-4000-8000-000000000001","name":"Entrée sous-workflow"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 1 }).toISO() }}"},"emailSearchFilters":{"to":"={{ $json.from_address || 'adresse-introuvable@invalid.invalid' }}"},"limit":40,"includeParts":["textContent"]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[260,0],"id":"a1000000-0000-4000-8000-000000000002","name":"Retrouver mes réponses précédentes","alwaysOutputData":true,"onError":"continueRegularOutput","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"jsCode":"// Assemble le prompt : mail reçu + historique des réponses précédentes à ce correspondant\\nconst src = $('Entrée sous-workflow').first().json;\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\n\\nconst ownText = (t) => String(t || '').replace(/\\\\r/g, '')\\n  .split(/\\\\n(?:>|Le .{5,90} a écrit|De ?:|From:|-----Original|On .{5,90} wrote)/)[0].trim();\\n\\nconst history = found\\n  .map(j => ({ date: new Date(j.envelope.date || 0), subject: j.envelope.subject || '', text: ownText(j.textContent) }))\\n  .filter(h => h.text.length >= 30)\\n  .sort((a, b) => b.date - a.date)\\n  .slice(0, 3)\\n  .map((h, n) => `--- Échange ${n + 1} (${h.date.toISOString().slice(0, 10)}, objet : ${h.subject}) ---\\\\n${h.text.slice(0, 700)}`)\\n  .join('\\\\n\\\\n');\\n\\nconst body = String(src.text || '').trim().slice(0, 4000);\\nconst prompt = [\\n  'MAIL REÇU',\\n  `De : ${src.from_name ? src.from_name + ' ' : ''}<${src.from_address}>`,\\n  `Objet : ${src.subject}`,\\n  `Date : ${src.date}`,\\n  `Résumé (assistant de tri) : ${src.resume || ''}`,\\n  '',\\n  'Contenu :',\\n  body || '(message sans texte)',\\n  '',\\n  'HISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)',\\n  history || \\"(aucun échange précédent trouvé : vouvoie par défaut)\\",\\n  '',\\n  'Rédige le brouillon de réponse.'\\n].join('\\\\n');\\n\\nreturn [{ json: { prompt, historyCount: history ? history.split('--- Échange ').length - 1 : 0 } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[520,0],"id":"a1000000-0000-4000-8000-000000000003","name":"Assembler le contexte"},{"parameters":{"promptType":"define","text":"={{ $json.prompt }}","messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu rédiges des BROUILLONS de réponses d'e-mails pour la boîte administrative d'EBANISTA (menuiserie / ébénisterie sur mesure). Cette boîte sert au secrétariat, à la comptabilité, aux ressources humaines et aux échanges avec les clients et les fournisseurs. La personne qui la gère relira et modifiera chaque brouillon avant de l'envoyer : tu écris à sa place, dans son style.\\n\\nRéponds UNIQUEMENT avec le corps du message : pas d'objet, pas de commentaire, pas de guillemets, pas de balises.\\n\\nSTYLE (tiré des mails envoyés depuis cette boîte) :\\n- Vouvoiement quasi systématique, ton poli, professionnel et courtois, sans familiarité. Tutoie uniquement si l'historique de ses échanges avec cette personne montre qu'elle la tutoie.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Bonjour Madame Nom,\\" / \\"Bonjour Monsieur Nom,\\" avec un interlocuteur formel. Mets un prénom ou un nom seulement si tu en es sûr.\\n- Phrases complètes et claires, paragraphes courts (3 à 8 lignes en général). Formules typiques : \\"Je reviens vers vous concernant …\\", \\"Merci pour votre retour.\\", \\"Merci beaucoup pour l'envoi de …\\", \\"Vous trouverez en pièce jointe …\\", \\"Je vous mets … en pièce jointe.\\".\\n- Demandes précises : \\"Pourriez-vous …\\", \\"Serait-il possible de …\\". Si plusieurs points, une liste à puces.\\n- Avant la fin : \\"Merci d'avance pour votre retour.\\" ou \\"Je vous remercie par avance pour votre retour.\\"\\n- Formule de fin : \\"Cordialement,\\" ou \\"Bien cordialement,\\", parfois \\"Bonne journée,\\" / \\"Belle journée,\\".\\n- Signature : écris exactement [À COMPLÉTER : signature] sur la dernière ligne, sous la formule de fin.\\n- Réclamation, litige ou retard (facture erronée, résiliation, livraison manquante) : ton ferme, calme et factuel ; rappelle les dates, références et faits qui figurent dans le mail reçu ; demande clairement ce qui est attendu et dans quel délai si le mail le permet.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un montant, un nombre d'heures, une date, un délai, un numéro de contrat ou de dossier, une référence, une quantité ni un engagement. Si une information nécessaire manque, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Les DÉCISIONS ne sont jamais à ta charge : accepter ou refuser une offre, valider un devis, passer ou annuler une commande, payer, fixer une date, accorder un geste commercial, valider une demande d'un salarié. N'écris jamais \\"oui\\", \\"c'est d'accord\\", \\"je confirme\\" ou \\"nous validons\\" à sa place. Écris [À COMPLÉTER : décision à prendre (ce qu'il faut trancher)] ou une réponse neutre (accuser réception, demander une précision, dire que tu reviens vers l'interlocuteur).\\n- N'ajoute AUCUNE précision (références, dimensions, quantités, noms de personnes, détails de paie ou de contrat) qui n'est pas dans le mail reçu, même si elle apparaît dans l'historique : l'historique ne sert qu'à choisir le ton (tu / vous), la salutation et la formule de fin. Ne reprends jamais d'informations personnelles d'un ancien échange.\\n- Sujets sensibles (paie, ressources humaines, rupture de contrat, litiges juridiques) : reste neutre et prudent, n'engage pas l'entreprise, laisse [À COMPLÉTER] pour toute information ou décision.\\n- Réponds à toutes les questions posées dans le mail reçu, point par point si nécessaire.\\n- Écris en français, sauf si l'interlocuteur écrit dans une autre langue : réponds alors dans sa langue.\\n- Ne cite pas l'historique et ne recopie pas le mail reçu."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[780,0],"id":"a1000000-0000-4000-8000-000000000004","name":"Rédiger le brouillon"},{"parameters":{"model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.4}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[820,220],"id":"a1000000-0000-4000-8000-000000000005","name":"Modèle Claude (brouillon)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"jsCode":"// Compose un e-mail RFC822 (réponse) à enregistrer dans le dossier Brouillons\\nconst src = $('Entrée sous-workflow').first().json;\\nconst draft = String($input.first().json.text || '').trim();\\nif (!draft) throw new Error('Brouillon vide renvoyé par le modèle');\\n\\nconst MY = { name: 'Ebanista', addr: 'comptabilite@ebanista.fr' };\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\n\\n// en-tête non ASCII -> mots encodés (RFC 2047), découpés en petits morceaux\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst displayName = (name) => {\\n  if (!name) return '';\\n  // nom non ASCII : un seul mot encodé (le découper en plusieurs mots encodés le coupe à l'affichage)\\n  if (!isAscii(name)) return `=?UTF-8?B?${b64(name)}?=`;\\n  return /[^\\\\w .'-]/.test(name) ? `\\"${name.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : name;\\n};\\n\\nlet subject = String(src.subject || '').trim();\\nwhile (/^(re|ré)\\\\s*:\\\\s*/i.test(subject)) subject = subject.replace(/^(re|ré)\\\\s*:\\\\s*/i, '');\\nsubject = 'Re: ' + subject;\\n\\nconst origId = src.message_id ? (String(src.message_id).startsWith('<') ? src.message_id : `<${src.message_id}>`) : '';\\nconst when = src.date ? new Date(src.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long', timeStyle: 'short' }) : '';\\nconst who = (src.from_name ? src.from_name + ' ' : '') + `<${src.from_address}>`;\\nconst quoted = String(src.text || '').replace(/\\\\r/g, '').trim().slice(0, 3000).split('\\\\n').map(l => '> ' + l).join('\\\\n');\\nconst text = `${draft}\\\\n\\\\n\\\\nLe ${when}, ${who} a écrit :\\\\n${quoted}\\\\n`;\\n\\nconst headers = [\\n  `From: ${displayName(MY.name)} <${MY.addr}>`,\\n  `To: ${src.from_name ? displayName(src.from_name) + ' ' : ''}<${src.from_address}>`,\\n  `Subject: ${encodeHeader(subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: <draft-${Date.now()}-${Math.random().toString(36).slice(2, 10)}@ebanista.fr>`,\\n  ...(origId ? [`In-Reply-To: ${origId}`, `References: ${origId}`] : []),\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst bodyB64 = b64(text.replace(/\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\n\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + bodyB64 + CRLF, subject, draftPreview: draft } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1100,0],"id":"a1000000-0000-4000-8000-000000000006","name":"Composer le brouillon"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Drafts"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1360,0],"id":"a1000000-0000-4000-8000-000000000007","name":"Enregistrer dans Brouillons","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}}]	{"Entrée sous-workflow":{"main":[[{"node":"Retrouver mes réponses précédentes","type":"main","index":0}]]},"Retrouver mes réponses précédentes":{"main":[[{"node":"Assembler le contexte","type":"main","index":0}]]},"Assembler le contexte":{"main":[[{"node":"Rédiger le brouillon","type":"main","index":0}]]},"Modèle Claude (brouillon)":{"ai_languageModel":[[{"node":"Rédiger le brouillon","type":"ai_languageModel","index":0}]]},"Rédiger le brouillon":{"main":[[{"node":"Composer le brouillon","type":"main","index":0}]]},"Composer le brouillon":{"main":[[{"node":"Enregistrer dans Brouillons","type":"main","index":0}]]}}	\N	f	\N	[]
