is', dateStyle: 'long', timeStyle: 'short' }) : '';\\n  const quoted = String(r.extrait || '').replace(/\\\\r/g, '').trim().split('\\\\n').map(l => '> ' + l).join('\\\\n');\\n  text += `\\\\n\\\\n\\\\nLe ${when}, ${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}> a écrit :\\\\n${quoted}\\\\n`;\\n}\\nreturn [{ json: {\\n  chat_id: j.chat_id, next: 'send', box: m[1], label: BOX.label,\\n  from: BOX.from, fromName: BOX.fromName,\\n  from_header: `${BOX.fromName} <${BOX.from}>`,\\n  to: d.to_address, to_name: d.to_name || '', subject: d.subject || '(sans objet)',\\n  in_reply_to: r && r.message_id ? r.message_id : '',\\n  text,\\n} }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1000,-200],"id":"79d4e2dc-187c-4164-b8e3-a96718f52787","name":"Traiter le bouton"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"e1f66b10-9e9b-4f30-8e9c-3343f1e4f119","leftValue":"={{ $json.next }}","rightValue":"send","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1250,-200],"id":"4fd79f5a-0d53-435d-9520-a28bc4f38b42","name":"Envoi demandé ?"},{"parameters":{"jsCode":"// Confirme l'envoi à Valentin et clôt la conversation\\nconst t = $('Traiter le bouton').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\ndelete sd.sessions[String(t.chat_id)];\\nlet copyOk = true;\\ntry {\\n  const r = $input.first().json;\\n  if (!r || r.error || r.deleted === false) copyOk = false;\\n} catch (e) { copyOk = false; }\\nreturn [{ json: { chat_id: t.chat_id, text: `✅ Mail envoyé depuis ${t.label}\\\\nÀ : ${t.to}\\\\nObjet : ${t.subject}` + (copyOk ? '\\\\nUne copie est enregistrée dans Envoyés.' : \\"\\\\n⚠️ La copie dans Envoyés n'a pas pu être enregistrée.\\") } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2150,-200],"id":"f4a39826-3c91-4166-a990-3967c18b2eb2","name":"Confirmer l'envoi"},{"parameters":{"chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,-200],"id":"505d1545-6bc7-4207-8ecf-dd8d4de76a71","name":"Confirmation Telegram","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"870e8c34-0684-4d6f-97fa-1b0a8c365e6d"},{"parameters":{"jsCode":"// L'envoi a échoué : on remet le brouillon en attente pour pouvoir réessayer\\nconst t = $('Traiter le bouton').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst s = (sd.sessions || {})[String(t.chat_id)];\\nif (s) { s.state = 'ready'; s.updated = Date.now(); }\\nlet why = '';\\ntry { why = String($input.first().json.error && ($input.first().json.error.message || $input.first().json.error) || '').slice(0, 200); } catch (e) {}\\nreturn [{ json: { chat_id: t.chat_id, text: `❌ L'envoi depuis ${t.label} a échoué${why ? ' : ' + why : ''}.\\\\nLe brouillon est conservé : vous pouvez réessayer avec le même bouton ou choisir l'autre boîte.` } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1900,-500],"id":"f85f8213-4bd3-46fe-b6a2-f61c6ab47926","name":"Échec de l'envoi"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"a73af186-0267-4d6d-b87a-ede1a14a727f","leftValue":"={{ $json.box }}","rightValue":"v","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1450,-200],"id":"ed60e3e3-fdf0-4a1d-b16d-2098047ce98e","name":"Boîte v.caufriez@ebanista.fr ?"},{"parameters":{"fromEmail":"={{ $json.from_header }}","toEmail":"={{ $json.to }}","subject":"={{ $json.subject }}","emailFormat":"text","text":"={{ $json.text }}","options":{"appendAttribution":false}},"type":"n8n-nodes-base.emailSend","typeVersi